import logging

def rate_limit(redis_client, ip: str, limit: int = 100) -> bool:
    try:
        count = redis_client.incr(ip)
        if count == 1:
            redis_client.expire(ip, 60)
        return count <= limit
    except Exception as e:
        logging.error(f'Rate limiter fail-open triggered: {e}')
        return True

