import pytest
from unittest.mock import MagicMock
from solution import rate_limit

@pytest.fixture
def mock_redis():
    return MagicMock()

def test_rate_limit_allows_under_threshold(mock_redis):
    mock_redis.incr.return_value = 50
    assert rate_limit(mock_redis, '127.0.0.1') is True

def test_rate_limit_blocks_over_threshold(mock_redis):
    mock_redis.incr.return_value = 101
    assert rate_limit(mock_redis, '127.0.0.1') is False
